            r = (r << 1) | ((dividend >> (HIGHEST_BIT - i)) & 1'b1);
            
            // Compare and subtract if possible
            if (r >= divisor) begin
                r = r - divisor;
                q[HIGHEST_BIT - i] = 1'b1;  // Set cur_ient quotient bit
            end else begin
                q[HIGHEST_BIT - i] = 1'b0;
            end
        end
    end

